    description: { de: "Ein gigantisches Laufwasserkraftwerk am unteren Mekong, das trotz ökologischer Bedenken hinsichtlich der Fischwanderung und Sedimentation gebaut wurde.", hu: "Egy gigantikus folyóvízi erőmű az alsó Mekongon, amely a halak vándorlásával és az üledékesedéssel kapcsolatos ökológiai aggályok ellenére épült.", ro: "Un proiect hidroenergetic uriaș pe cursul inferior al Mekongului, construit în ciuda îngrijorărilor ecologice privind migrația peștilor și sedimentarea.", en: "A massive run-of-the-river hydroelectric power plant on the lower Mekong, built despite ecological concerns regarding fish migration and sedimentation." , es: "Una gigantesca central hidroeléctrica de agua fluyente en el bajo Mekong, construida a pesar de las preocupaciones ecológicas sobre la migración de peces y la sedimentación.", pt: "Uma central hidroelétrica de fio de água gigante no baixo Mekong, construída apesar das preocupações ecológicas sobre a migração de peixes e a sedimentação.", fr: "Une gigantesque centrale hydroélectrique au fil de l'eau sur le bas Mékong, construite malgré les préoccupations écologiques concernant la migration des poissons et la sédimentation."},
