    description: { de: "Das wichtigste Binnenlogistikzentrum des Landes in der Nähe von Vientiane, das den Schienengüterverkehr effizient mit dem Straßennetz verbindet.", hu: "Az ország legfontosabb belföldi logisztikai központja Vientiane közelében, amely hatékonyan összeköti a vasúti teherforgalmat az úthálózattal.", ro: "Cel mai important centru logistic intern al țării, lângă Vientiane, conectând eficient transportul feroviar de marfă cu rețeaua rutieră.", en: "The country's most important inland logistics center near Vientiane, efficiently connecting rail freight traffic with the road network." , es: "El centro logístico interior más importante del país, cerca de Vientiane, que conecta de manera eficiente el transporte de mercancías por ferrocarril con la red de carreteras.", pt: "O centro logístico interior mais importante do país, perto de Vientiane, que liga eficientemente o transporte ferroviário de mercadorias à rede rodoviária.", fr: "Le principal centre logistique intérieur du pays, situé près de Vientiane, reliant efficacement le fret ferroviaire au réseau routier."},
